import {useState, useRef, useCallback, useEffect} from 'react'
import {IconButton, type IconButtonProps} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import type {Icon} from '@primer/octicons-react'
import type {Repository} from '@github-ui/current-repository'
import {useSearchParams} from '@github-ui/use-navigate'
import {NewAgentTaskForm} from '@github-ui/new-agent-task-form/NewAgentTaskForm'
import {useCreateAPITask} from '@github-ui/agent-sessions/hooks/use-create-api-task'
import type {CreateAPITaskParams} from '@github-ui/agent-sessions/types/api-task'
import {
  getFlatTaskList,
  repoTasksQueryKey,
  setFlatTaskList,
  REPO_TASKS_PAGE_SIZE,
  type FetchRepoTasksResponse,
} from '@github-ui/agent-sessions/hooks/repo-task-utils'

export interface NewRepoAgentTaskButtonProps extends Pick<IconButtonProps, 'size' | 'variant' | 'tooltipDirection'> {
  repository: Repository
  currentUserId?: number
  currentUserLogin?: string
  icon: Icon
  label?: string
  eventType: string
  initialText?: string
  /** Maximum height for the textarea input in pixels */
  maxTextareaHeight?: number
  /** If provided, the component becomes controlled */
  isOpen?: boolean
  /** Callback when dialog should close (required if isOpen is provided) */
  onOpenChange?: (open: boolean) => void
  /** Optional identifiers for tracking (e.g., parent workflow_run_id) */
  eventIdentifiers?: string[]
  decoupledModeEnabled: boolean
}

export function NewRepoAgentTaskButton({
  repository,
  currentUserId,
  currentUserLogin,
  icon,
  label = 'New session',
  size,
  variant,
  tooltipDirection,
  eventType,
  initialText,
  maxTextareaHeight,
  isOpen: controlledIsOpen,
  onOpenChange,
  eventIdentifiers,
  decoupledModeEnabled,
}: NewRepoAgentTaskButtonProps) {
  const [internalIsOpen, setInternalIsOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)

  // Support both controlled and uncontrolled modes
  const isControlled = controlledIsOpen !== undefined
  const isOpen = isControlled ? controlledIsOpen : internalIsOpen

  const handleOpen = useCallback(() => {
    if (isControlled) {
      onOpenChange?.(true)
    } else {
      setInternalIsOpen(true)
    }
  }, [isControlled, onOpenChange])

  const handleClose = useCallback(() => {
    if (isControlled) {
      onOpenChange?.(false)
    } else {
      setInternalIsOpen(false)
    }
  }, [isControlled, onOpenChange])

  const dialogTitle = `${label} in ${repository.ownerLogin}/${repository.name}`

  return (
    <>
      <IconButton
        ref={buttonRef}
        icon={icon}
        aria-label={label}
        size={size}
        tooltipDirection={tooltipDirection}
        variant={variant}
        onClick={handleOpen}
      />
      {isOpen && (
        <Dialog title={dialogTitle} onClose={handleClose} returnFocusRef={buttonRef} position={{narrow: 'fullscreen'}}>
          <Dialog.Body className="p-0">
            <NewRepoAgentTaskDialogContent
              repository={repository}
              currentUserId={currentUserId}
              currentUserLogin={currentUserLogin}
              eventType={eventType}
              onClose={handleClose}
              initialText={initialText}
              maxTextareaHeight={maxTextareaHeight}
              eventIdentifiers={eventIdentifiers}
              decoupledModeEnabled={decoupledModeEnabled}
            />
          </Dialog.Body>
        </Dialog>
      )}
    </>
  )
}

interface NewRepoAgentTaskDialogContentProps {
  repository: Repository
  currentUserId?: number
  currentUserLogin?: string
  eventType: string
  onClose: () => void
  initialText?: string
  maxTextareaHeight?: number
  eventIdentifiers?: string[]
  decoupledModeEnabled: boolean
}

function NewRepoAgentTaskDialogContent({
  repository,
  currentUserId,
  currentUserLogin,
  eventType,
  onClose,
  initialText,
  maxTextareaHeight,
  eventIdentifiers,
  decoupledModeEnabled,
}: NewRepoAgentTaskDialogContentProps) {
  const [searchParams] = useSearchParams()
  const authorFilter = searchParams.get('author')
  const isFilteredByCurrentUser = currentUserLogin ? authorFilter === currentUserLogin : false
  const queryUserId = isFilteredByCurrentUser ? currentUserId : undefined
  const queryKey = repoTasksQueryKey(repository.ownerLogin, repository.name, queryUserId, 1, false)
  const {createTask} = useCreateAPITask<FetchRepoTasksResponse>({
    queryKey,
    getFlatTaskList,
    setFlatTaskList,
    pageSize: REPO_TASKS_PAGE_SIZE,
    decoupledModeEnabled,
  })
  const textAreaRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    // Autofocus the textarea when the dialog opens
    textAreaRef.current?.focus()
  }, [])

  const handleCreateTask = useCallback(
    (params: CreateAPITaskParams) => {
      createTask({
        ...params,
        eventType,
        eventIdentifiers,
      })
    },
    [createTask, eventType, eventIdentifiers],
  )

  return (
    <NewAgentTaskForm
      createTask={handleCreateTask}
      currentRepo={repository}
      onCreate={onClose}
      hideRepoSelector
      eventType={eventType}
      showHeader={false}
      textAreaRef={textAreaRef}
      initialText={initialText}
      maxTextareaHeight={maxTextareaHeight}
      isInPortal
      decoupledModeEnabled={decoupledModeEnabled}
    />
  )
}
