import type {ToolUserRequestedMessage} from '../../types/session'
import {isExitPlanModeArguments} from '../../types/session'
import {ResolvedPlanApproval} from './ResolvedPlanApproval'

interface PlanApprovalLogEntryProps {
  prompt: ToolUserRequestedMessage
}

/** Renders a resolved exit_plan_mode prompt in the session logs timeline. */
export function PlanApprovalLogEntry({prompt}: PlanApprovalLogEntryProps) {
  if (!isExitPlanModeArguments(prompt.arguments)) {
    return null
  }

  return <ResolvedPlanApproval />
}
