import type {ToolUserRequestedMessage} from '../../types/session'
import {isAskUserArguments, isElicitationAskUser} from '../../types/session'
import {ResolvedAskUser} from './ResolvedAskUser'

interface AskUserLogEntryProps {
  prompt: ToolUserRequestedMessage
  resolvedAnswer?: string
}

/** Renders a resolved ask_user prompt in the session logs timeline. */
export function AskUserLogEntry({prompt, resolvedAnswer}: AskUserLogEntryProps) {
  const {arguments: args} = prompt

  if (!isAskUserArguments(args)) {
    return null
  }

  const displayText = isElicitationAskUser(args) ? args.message : args.question
  return <ResolvedAskUser question={displayText} resolvedAnswer={resolvedAnswer} />
}
