import {getSortedResourceIds} from '@github-ui/agent-sessions/hooks/usePullRequests'
import {type FetchTasksResponse, getAgentTasksQueryKey} from '@github-ui/agent-sessions/hooks/useTasks'
import type {IdToPullRequestMap} from '@github-ui/agent-sessions/types/pull'
import type {BaseTask} from '@github-ui/agent-sessions/types/task'
import {useQuery} from '@github-ui/react-query'

/**
 * Hook to sync with live agent task data including states and titles
 * This subscribes to changes from both the agent-tasks cache and pull-requests cache
 * to get live state and title updates without making additional API calls.
 *
 * @returns A map of task URLs to their current state and title
 */
export function useTaskStateSync(): Map<string, {state: string; title?: string}> {
  const tasksQueryKey = getAgentTasksQueryKey(1, 'active')
  const {data: cachedData} = useQuery<FetchTasksResponse>({
    queryKey: tasksQueryKey,
    queryFn: () => [[], false, undefined], // this needs to be defined to appease useQuery, but we don't actually use it
    enabled: false,
    notifyOnChangeProps: ['data'],
  })
  const cachedTasks: BaseTask[] = cachedData?.[0] ?? []

  const pullRequestIds = getSortedResourceIds(cachedTasks || [])
  const {data: pullRequestsMap} = useQuery<IdToPullRequestMap>({
    queryKey: ['agent-sessions-pull-requests', pullRequestIds],
    queryFn: () => ({}),
    enabled: false,
    notifyOnChangeProps: ['data'],
  })

  const taskStateMap = new Map<string, {state: string; title?: string}>()

  if (cachedTasks.length > 0) {
    for (const task of cachedTasks) {
      if (!task.resource_global_id) {
        continue
      }

      const taskUrl = `https://github.com/copilot/tasks/pull/${task.resource_global_id}`
      const pull = task.resource_id && pullRequestsMap ? pullRequestsMap[task.resource_id] : undefined

      const taskData = {
        state: task.latest_session_state,
        title: pull?.title,
      }

      taskStateMap.set(taskUrl, taskData)
    }
  }

  return taskStateMap
}
