import type {ReactNode} from 'react'
import {useState} from 'react'
import {NewToolHeader} from './tool/NewToolHeader'
import styles from './ResolvedPromptDisplay.module.css'

export interface ResolvedPromptDisplayProps {
  /** Leading icon for the header (e.g. QuestionIcon, ShieldCheckIcon) */
  icon?: ReactNode
  /** Title text shown in the header */
  title: string
  /** Optional subtitle shown after the title */
  subtitle?: string
  /** Expandable content shown below the header when toggled */
  children?: ReactNode
}

/** Renders a resolved interactive prompt in the same style as Tool calls */
export function ResolvedPromptDisplay({icon, title, subtitle, children}: ResolvedPromptDisplayProps) {
  const hasContent = children != null
  const [isCollapsed, setIsCollapsed] = useState(!hasContent)

  const displayTitle = subtitle ? `${title} · ${subtitle}` : title

  return (
    <div className={styles.container}>
      <NewToolHeader
        leadingVisual={icon}
        title={displayTitle}
        isCollapsed={isCollapsed}
        hasReferences={hasContent}
        onToggle={() => setIsCollapsed(prev => !prev)}
      />
      {!isCollapsed && hasContent ? <div className={styles.content}>{children}</div> : null}
    </div>
  )
}
