import {
  CodescanCheckmarkIcon,
  CodespacesIcon,
  FileAddedIcon,
  FileDirectoryIcon,
  FileDiffIcon,
  GitPullRequestIcon,
  GlobeIcon,
  LightBulbIcon,
  McpIcon,
  SearchIcon,
  TasklistIcon,
  TerminalIcon,
} from '@primer/octicons-react'
import type {ToolName} from '../../../types/session'
import {TOOL_NAMES} from '../../../constants/tool-names'
import {ViewFilesIcon} from '../../CustomIcons'

export function getToolIcon(toolName: ToolName = '', mcpToolNameMappings?: Record<string, string>) {
  switch (toolName) {
    case TOOL_NAMES.APPLY_PATCH:
      return <FileDiffIcon className="fgColor-attention" aria-label="File Edit: " />
    case TOOL_NAMES.BASH:
    case TOOL_NAMES.WRITE_BASH:
    case TOOL_NAMES.READ_BASH:
    case TOOL_NAMES.STOP_BASH:
    case TOOL_NAMES.LIST_BASH:
    case TOOL_NAMES.ASYNC_BASH:
    case TOOL_NAMES.READ_ASYNC_BASH:
    case TOOL_NAMES.STOP_ASYNC_BASH:
    case TOOL_NAMES.POWERSHELL:
    case TOOL_NAMES.WRITE_POWERSHELL:
    case TOOL_NAMES.READ_POWERSHELL:
    case TOOL_NAMES.STOP_POWERSHELL:
    case TOOL_NAMES.LIST_POWERSHELL:
      return <TerminalIcon aria-label="CLI output: " />
    case TOOL_NAMES.THINK:
      return <LightBulbIcon aria-label="Copilot Thought: " />
    case TOOL_NAMES.STR_REPLACE_EDITOR:
    case TOOL_NAMES.STR_REPLACE:
    case TOOL_NAMES.EDIT:
      return <FileDiffIcon className="fgColor-attention" aria-label="File Edit: " />
    case TOOL_NAMES.CREATE:
      return <FileAddedIcon className="fgColor-success" aria-label="File Creation: " />
    case TOOL_NAMES.VIEW:
      return <ViewFilesIcon aria-label="View File: " />
    case TOOL_NAMES.GREP:
    case TOOL_NAMES.RG:
    case TOOL_NAMES.SEARCH_CODE_SUBAGENT:
      return <SearchIcon aria-label="Search: " />
    case TOOL_NAMES.WEB_SEARCH:
      return <SearchIcon aria-label="Web Search: " />
    case TOOL_NAMES.WEB_FETCH:
      return <GlobeIcon aria-label="Web Fetch: " />
    case TOOL_NAMES.GLOB:
      return <FileDirectoryIcon aria-label="Find files: " />
    case TOOL_NAMES.RUN_CUSTOM_SETUP_STEP:
    case TOOL_NAMES.RUN_SETUP:
      return <CodespacesIcon aria-label="Custom Setup Run: " />
    case TOOL_NAMES.PROPOSE_WORK:
      return <TasklistIcon aria-label="Propose Work: " />
    case TOOL_NAMES.CODE_REVIEW:
      return <CodescanCheckmarkIcon aria-label="Code Review: " />
    case TOOL_NAMES.CODEQL_CHECKER:
      return <CodescanCheckmarkIcon aria-label="CodeQL Scan: " />
    case TOOL_NAMES.CREATE_PULL_REQUEST:
      return <GitPullRequestIcon aria-label="Create pull request: " />
    case TOOL_NAMES.PARALLEL_VALIDATION:
      return <CodescanCheckmarkIcon aria-label="Parallel Validation: " />
    case TOOL_NAMES.REPORT_PROGRESS:
    case TOOL_NAMES.REPLY_TO_COMMENT:
      return <TerminalIcon aria-label="Tool output: " />
    default:
      if (mcpToolNameMappings && Object.prototype.hasOwnProperty.call(mcpToolNameMappings, toolName)) {
        return <McpIcon aria-label="MCP tool: " />
      }
      return <TerminalIcon aria-label="Tool output: " />
  }
}
