import {ShieldCheckIcon} from '@primer/octicons-react'
import {ResolvedPromptDisplay} from './ResolvedPromptDisplay'

export interface ResolvedPermissionProps {
  /** The kind of permission: 'commands', 'shell', 'write', 'mcp', or a tool name */
  kind: string
  /** The tool requesting permission */
  toolName?: string
  /** Command text or filename to display */
  detail?: string
}

/** Resolved permission prompt shown in the session timeline — only for denied permissions */
export function ResolvedPermission({kind, toolName, detail}: ResolvedPermissionProps) {
  const isCommand = kind === 'commands' || kind === 'shell'
  const isWrite = kind === 'write'
  const label = isCommand ? 'Run command' : isWrite ? 'Edit file' : `Permission: ${toolName ?? kind}`
  const subtitle = detail ? `Denied · ${detail}` : 'Denied'

  return (
    <ResolvedPromptDisplay icon={<ShieldCheckIcon size={16} />} title={label} subtitle={subtitle}>
      {detail}
    </ResolvedPromptDisplay>
  )
}
