import type {ToolUserRequestedMessage} from '../../types/session'
import {isPermissionRequestArguments} from '../../types/session'
import {ResolvedPermission} from './ResolvedPermission'

interface PermissionLogEntryProps {
  prompt: ToolUserRequestedMessage
  resolvedAnswer?: string
}

/** Renders a resolved permission_request prompt in the session logs timeline.
 *  Accepted → hidden (returns null). Denied → shows ResolvedPermission. */
export function PermissionLogEntry({prompt, resolvedAnswer}: PermissionLogEntryProps) {
  const {arguments: args} = prompt

  if (!isPermissionRequestArguments(args)) {
    return null
  }

  const wasDenied = resolvedAnswer === 'Denied' || resolvedAnswer === 'false'
  if (!wasDenied) {
    return null
  }

  return (
    <ResolvedPermission kind={args.kind} toolName={args.toolName} detail={args.command || args.filePath || args.diff} />
  )
}
