import {useState, type ReactNode} from 'react'
import type {GroupHeaderFn, ToolGroup} from './types'
import {NewToolHeader} from '../tool/NewToolHeader'
import styles from './ToolGroupRenderer.module.css'

type ToolGroupRendererProps = {
  group: ToolGroup
  groupHeaderFn: GroupHeaderFn
  children: ReactNode
}

export function ToolGroupRenderer({group, groupHeaderFn, children}: ToolGroupRendererProps) {
  const headerData = groupHeaderFn(group)
  // Groups with 30+ tools start collapsed to avoid overwhelming the UI
  const [isCollapsed, setIsCollapsed] = useState(group.entries.length >= 30)

  const handleToggle = () => {
    setIsCollapsed(prev => !prev)
  }

  return (
    <div>
      <div className={styles.toolGroupHeader}>
        <NewToolHeader
          title={headerData.title}
          leadingVisual={headerData.leadingVisual}
          isError={false}
          isPending={false}
          isCollapsed={isCollapsed}
          isGroupHeader
          onToggle={handleToggle}
        />
      </div>
      {!isCollapsed && (
        <div className={styles.toolGroupContentWrapper}>
          <div className={styles.connectorLine} />
          <div className={styles.toolGroupContent}>{children}</div>
        </div>
      )}
    </div>
  )
}
