import type {ToolUserRequestedMessage, LogEntry} from '../../types/session'
import type {OptimisticPromptResponse} from '../../contexts/OptimisticLogsContext'
import {findToolResponse, formatOptimisticResponse} from './prompt-log-utils'
import {AskUserLogEntry} from './AskUserLogEntry'
import {PlanApprovalLogEntry} from './PlanApprovalLogEntry'
import {PermissionLogEntry} from './PermissionLogEntry'

interface InteractivePromptLogEntryProps {
  prompt: ToolUserRequestedMessage
  logsData?: LogEntry[]
  optimisticResponse?: OptimisticPromptResponse
}

/**
 * Renders an interactive prompt (ask_user, permission_request, exit_plan_mode)
 * in the session logs timeline. Resolves the response centrally and delegates
 * to the appropriate specialized component.
 */
export function InteractivePromptLogEntry({prompt, logsData, optimisticResponse}: InteractivePromptLogEntryProps) {
  const {toolCallId, toolName} = prompt

  const serverResponse = findToolResponse(toolCallId, logsData)
  const hasOptimistic = optimisticResponse !== undefined && optimisticResponse.status === 'pending'
  const optimisticAnswer = hasOptimistic
    ? formatOptimisticResponse(optimisticResponse.response, optimisticResponse.commandType)
    : undefined
  const resolvedAnswer = serverResponse ?? optimisticAnswer

  switch (toolName) {
    case 'ask_user':
      return <AskUserLogEntry prompt={prompt} resolvedAnswer={resolvedAnswer} />
    case 'exit_plan_mode':
      return <PlanApprovalLogEntry prompt={prompt} />
    case 'permission_request':
      return <PermissionLogEntry prompt={prompt} resolvedAnswer={resolvedAnswer} />
    default:
      return null
  }
}
