import {useMemo} from 'react'
import type {LogEntry} from '../types/session'
import type {NormalizedPrompt, PendingPromptResult} from '../components/session-logs/prompt-log-utils'
import {extractPromptFromEntry, isPromptResolved} from '../components/session-logs/prompt-log-utils'

const NO_PENDING_PROMPT: PendingPromptResult = {
  pendingPrompt: null,
  pendingToolCallId: null,
  hasPendingPrompt: false,
}

/**
 * Computes the last unresolved interactive prompt from session logs.
 */
export function computePendingPrompt(logs: LogEntry[] | undefined): PendingPromptResult {
  if (!logs?.length) {
    return NO_PENDING_PROMPT
  }

  // Find CLI prompts in logs (iterate in reverse to find the latest)
  // We check ALL prompts, not just the last entry, because there might be
  // other events after the prompt (like tool outputs for other tools)
  const prompts: Array<{prompt: NormalizedPrompt; index: number}> = []

  for (let i = 0; i < logs.length; i++) {
    const entry = logs[i]
    if (entry) {
      const prompt = extractPromptFromEntry(entry)
      if (prompt) {
        prompts.push({prompt, index: i})
      }
    }
  }

  // Check each prompt from latest to earliest to find the last unresolved one
  for (let i = prompts.length - 1; i >= 0; i--) {
    const item = prompts[i]
    if (item && !isPromptResolved(item.prompt.toolCallId, logs)) {
      return {
        pendingPrompt: item.prompt,
        pendingToolCallId: item.prompt.toolCallId,
        hasPendingPrompt: true,
      }
    }
  }

  return NO_PENDING_PROMPT
}

/**
 * Hook that detects the last unresolved CLI prompt from session logs.
 *
 * Used to:
 * 1. Filter pending prompts from inline log display
 * 2. Show pending prompts prominently in chat input area
 *
 * @param logs - The session log entries to analyze
 * @returns The pending prompt info, or null values if no pending prompt
 */
export function usePendingPrompt(logs: LogEntry[] | undefined): PendingPromptResult {
  return useMemo(() => computePendingPrompt(logs), [logs])
}
