import {QuestionIcon} from '@primer/octicons-react'
import type {ReactNode} from 'react'
import {ResolvedPromptDisplay} from './ResolvedPromptDisplay'

export interface ResolvedAskUserProps {
  /** The question that was asked */
  question: string
  /** Short title for the card header (defaults to question) */
  title?: string
  /** Whether this prompt was skipped/aborted */
  isSkipped?: boolean
  /** The answer that was given */
  resolvedAnswer?: string
}

/** Resolved ask_user prompt shown in the session timeline */
export function ResolvedAskUser({question, title, isSkipped = false, resolvedAnswer}: ResolvedAskUserProps) {
  const cardTitle = title ?? question

  let displayAnswer: ReactNode | undefined
  if (isSkipped) {
    displayAnswer = undefined
  } else if (resolvedAnswer === 'Declined') {
    displayAnswer = 'Declined'
  } else if (resolvedAnswer) {
    displayAnswer = resolvedAnswer
  }

  return (
    <ResolvedPromptDisplay
      icon={<QuestionIcon size={16} />}
      title={cardTitle}
      subtitle={isSkipped ? 'Skipped' : undefined}
    >
      {displayAnswer}
    </ResolvedPromptDisplay>
  )
}
