import type {Command, LogEntry} from '../types/session'
import {isCompletionUserMessage} from '../types/session'

/**
 * Checks if a command appears in the logs by matching the source field.
 * sweagentd sets source to `command-{external_id}` when processing commands.
 */
export function isCommandInLogs(command: Command, logEntry: LogEntry): boolean {
  return isCompletionUserMessage(logEntry) && logEntry.source === `command-${command.external_id}`
}

/**
 * Filters commands to return only those that are still pending (not yet processed or shown in logs).
 *
 * - CLI: marks commands 'completed' immediately, so filter by state works
 * - sweagentd: commands stay 'in_progress' forever, so also check source matching
 * - Failed commands are shown because they never appear in logs
 */
export function getPendingCommands(commandsData: Command[] | undefined, logsData: LogEntry[] | undefined): Command[] {
  if (!commandsData?.length) {
    return []
  }

  return commandsData.filter(command => {
    // Hide completed and dismissed commands (successfully processed or session ended)
    if (command.state === 'completed' || command.state === 'dismissed') {
      return false
    }

    // For in_progress commands, check if they're already in logs (sweagentd sets source)
    if (command.state === 'in_progress' && logsData?.some(log => isCommandInLogs(command, log))) {
      return false
    }

    // Show queued, failed, and in_progress commands not yet in logs
    return true
  })
}
